import { FormEvent, useState } from 'react';
import { JxButton, JxInputField, JxToastViewport, useJxToastQueue } from '@jinx-ui/react';

function SubscribeToastForm() {
  const [email, setEmail] = useState('');
  const toasts = useJxToastQueue();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${email}`,
      variant: 'success',
    });
    setEmail('');
  };

  return (
    <>
      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 8px)' }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          name="email"
          required
          value={email}
          onChange={(event) => setEmail(event.target.value)}
        />
        <JxButton type="submit">Подписаться</JxButton>
      </form>
      <JxToastViewport items={toasts.items} onDismiss={toasts.dismiss} position="top-right" />
    </>
  );
}

export default SubscribeToastForm;

